export const SchoolRegionKeyToLabel = {
  'CentralFraser': 'Central Fraser',
  'EastValley': 'East Valley',
  'WestValley': 'West Valley',
  'NorthRural': 'North Rural'
} as const;
export type SchoolRegionKey = keyof typeof SchoolRegionKeyToLabel;

export const SchoolSchoolTypeKeyToLabel = {
  'Elementary': 'Elementary',
  'Middle': 'Middle',
  'Secondary': 'Secondary',
  'K12': 'K-12'
} as const;
export type SchoolSchoolTypeKey = keyof typeof SchoolSchoolTypeKeyToLabel;

export interface School {
  /**
   * @displayName School ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName School Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  schoolName: string;
  /**
   * @displayName Capacity
   * @validationRule Required for create/update operations
   */
  capacity: number;
  /**
   * @displayName Is Active
   * @validationRule Required for create/update operations
   */
  isActive: boolean;
  /**
   * @displayName Municipality
   * @validationRule Required for create/update operations
   */
  municipality: string;
  /**
   * @displayName Province
   * @validationRule Required for create/update operations
   */
  province: string;
  /**
   * @displayName Region
   * @validationRule Required for create/update operations
   */
  regionKey: SchoolRegionKey;
  /**
   * @displayName School Number
   * @validationRule Required for create/update operations
   */
  schoolNumber: string;
  /**
   * @displayName School Type
   * @validationRule Required for create/update operations
   */
  schoolTypeKey: SchoolSchoolTypeKey;
}

export const _School = 'School' as const;